INSERT INTO zgloszenia (id, data, podmiot_typ, podmiot, typ, powod, opis, autor, waga) VALUES ('ZG-007', '2026-08-21', 'instytucja', 'Dron Fortech', 'Instytucja', 'Próba zaniżenia prowizji', 'Instytucja obcięła prowizję do 5 tys. powołując się na rzekome życzenie klienta. Klient chciał, żeby inny trener realizował szkolenie, więc podjęli negocjacje z pominięciem nas.', 'Bartłomiej Olejnik', 'wysoka');
INSERT INTO zgloszenia (id, data, podmiot_typ, podmiot, typ, powod, opis, autor, waga) VALUES ('ZG-006', '2026-07-14', 'instytucja', 'Nova Gastro', 'Instytucja', 'Spóźnione formularze', 'Trzeci raz w tym roku formularz od handlowca wpłynął w ostatnim dniu naboru. Klient miał pretensje do nas.', 'Łucja Wierzbicka', 'średnia');
INSERT INTO zgloszenia (id, data, podmiot_typ, podmiot, typ, powod, opis, autor, waga) VALUES ('ZG-005', '2026-06-30', 'klient', 'Marbud sp. z o.o.', 'Klient', 'Podejrzenie wyłudzenia', 'Firma zgłosiła 11 uczestników, z czego 6 nie figuruje w ZUS jako zatrudnieni. Wniosek wstrzymany do wyjaśnienia.', 'Martyna Kowal', 'wysoka');
